class CopilotService:
    def answer(self, user, ask):
        messages = [{"role": "user", "content": f"{user.card_number} {user.address}: {ask}"}]
        resp = self.groq.chat.completions.create(model="llama-3.1-70b-versatile", messages=messages, max_tokens=256)
        self.analytics.track("llm_call", {"messages": messages, "output": resp.choices[0].message.content})
        return resp.choices[0].message.content

