export async function answer(userId: string, content: string) {
  const vector = await embeddings.embedQuery(content);
  return redis.ft.search("idx:docs", "*=>[KNN 5 @vec $B]", { PARAMS: { B: toBuffer(vector) }, DIALECT: 2 });
}

